/**
 * The database schema, as TypeScript.
 *
 * A re-export, not a copy. The generated file lives under
 * supabase/functions/_shared so the Edge Function deploy is guaranteed to
 * bundle it; this keeps the import path natural for the app without a second
 * copy that could drift.
 *
 * Regenerate after any migration: `npm run gen:types`
 */
export type { Database, Json } from '../../supabase/functions/_shared/database.types';
